const input = $input.all()[0].json.body || $input.all()[0].json;

if (typeof $workflow !== 'undefined' && $workflow.staticData) {
    $workflow.staticData.totalTokens = 0; // Reset token về 0 cho phiên mới
}

return [
  {
    json: {
      item_ids: input.item_ids || [],
      category_id: input.category_id,
      log_id: input.log_id,
      app_url: 'https://trends-tools-v2.vercel.app'
    }
  }
];

const items = $input.all();
if (items.length === 0) return [];
const item_ids = items.map(e => e.json.item_ids).filter(Boolean);
return [{
    json: {
        item_ids: item_ids
    }
}];

const input = $input.all()[0].json;
const rawTrends = input.raw_trends || [];
const memoryRules = input.memory_rules || [];
const approvedTrends = input.approved_trends || [];
const settings = input.settings || {};

let memoryPrompt = "";
if (memoryRules.length > 0) {
    memoryPrompt = `\nQUY TẮC BỘ NHỚ LỊCH SỬ TỪ NGƯỜI DÙNG (BẮT BUỘC TUÂN THỦ TUYỆT ĐỐI):\n`;
    memoryRules.forEach((rule, idx) => {
        memoryPrompt += `- [Quy tắc ${idx + 1} - Loại ${rule.rule_type}]: ${rule.user_feedback}`;
        if (rule.example_case) {
            memoryPrompt += ` (Ví dụ: ${rule.example_case})`;
        }
        memoryPrompt += `\n`;
    });
}

let historyPrompt = "";
if (approvedTrends.length > 0) {
    historyPrompt = `\nDANH SÁCH CÁC TREND ĐÃ DUYỆT GẦN ĐÂY (TRÁNH TRÙNG LẶP HOẶC TẠO LẠI TRÙNG):\n(Dưới đây là các chủ đề đã được duyệt đăng gần đây. Nếu các video mới thuộc một trong các sự kiện này, hãy cân nhắc xem có phải sự kiện mới hay không. Nếu là cùng một sự kiện cũ, hãy bỏ qua không tạo trend mới để tránh lặp lại tin cũ trên kênh):\n`;
    approvedTrends.forEach((t, idx) => {
        historyPrompt += `- Trend đã duyệt ${idx + 1}: ${t.trend_name} (${t.viral_reason})\n`;
    });
}

const trendsContext = rawTrends.map((t, index) => {
    return `Trend ${index + 1}:
- Tên: ${t.trend_name}
- Lý do Viral: ${t.viral_reason}
- Video count: ${t.videos_count}
- IDs bài viết: ${t.related_ids ? t.related_ids.join(', ') : t.crawled_data_id}
`;
}).join('\n---\n');

const base_prompt = "Bạn là chuyên gia phân tích dữ liệu mạng xã hội (Data Scientist).\nNhiệm vụ của bạn là gộp (Reduce) danh sách các Trend thô bị trùng lặp dưới đây thành một danh sách các Trend tinh hoa duy nhất.\n\nLUẬT GỘP TREND & LỌC ĐIỀU KIỆN (BẮT BUỘC):\n1. Định nghĩa \"Trùng lặp\" để gộp:\n   - CHỈ gộp các Trend thô nói về cùng 1 sự việc/sự kiện cụ thể (ví dụ: cùng một vụ cháy ở xưởng mút Hương Lộ 2, cùng một vụ án mẹ kế ở Quảng Ninh, cùng một sự việc anh Hoàng dùng bình cứu hỏa cứu người ở Hải Phòng, cùng một vụ bão/sóng lớn ở thành phố Nichinan Nhật Bản).\n   - CHỈ gộp các Trend thô sử dụng chung 1 bài nhạc nền (music), cùng 1 format kịch bản (ví dụ: nhờ bố trông cá và cái kết, nắp mì tôm bói quẻ).\n   - TUYỆT ĐỐI KHÔNG được gộp các sự việc/tin tức/chủ đề khác nhau vào chung một nhóm lớn mang tên chung chung (ví dụ: KHÔNG được gom các vụ án, vụ cháy, phạt xe khách khác nhau thành một trend chung mang tên \"Tin tức xã hội\", \"Vấn đề pháp luật\", \"Câu chuyện nhân văn\", v.v.). Mỗi sự việc/sự kiện cụ thể phải là một Trend riêng biệt.\n\n2. Phân rã (Split) các trend thô bị gom nhóm quá rộng:\n   - Nếu trong danh sách các Trend thô đầu vào có chứa các trend bị gom nhóm quá rộng hoặc chứa nhiều sự việc khác nhau (ví dụ: 'Chuyện lạ đời/Tâm linh/Kỳ quái khó lý giải' chứa cả vụ chim lạ lẫn vụ giả chết và mì tôm; hoặc 'Tin tức xã hội' chứa cả vụ tôm chết lẫn cháy xưởng), bạn BẮT BUỘC phải phân rã (Split) chúng thành các trend cụ thể riêng biệt (ví dụ: tách thành 'Chú chim lạ đậu trên di ảnh ở Hưng Yên', 'Thanh niên giả chết để chia tay', 'Mì tôm bói quẻ Nhật Bản').\n\n3. Đặt \"Tên Trend\" cụ thể và chi tiết:\n   - Tên Trend phải phản ánh đúng sự việc/kịch bản cụ thể đó (ví dụ: \"Hình ảnh sóng lớn dữ dội sau bão tại Nhật Bản\", \"Vụ cháy xưởng sản xuất mút tại Hương Lộ 2 TPHCM\", \"Anh hùng Hải Phòng dùng bình cứu hỏa giải cứu người phụ nữ bị đâm\").\n   - Tuyệt đối không đặt tên bao quát, mơ hồ, mang tính danh mục chung chung.\n\n4. Phân tích & Bảo toàn điều kiện lọc tối thiểu:\n   - Trend sau khi gộp hoặc đứng riêng lẻ phải thỏa mãn bộ lọc:\n     * Có tổng cộng từ " + settings.min_videos + " bài viết (IDs) trở lên.\n     * Xuất hiện ở từ " + settings.min_channels + " kênh khác nhau trở lên.\n     Nếu không thỏa mãn cả hai điều kiện trên, hãy LOẠI BỎ hoàn toàn trend đó khỏi danh sách kết quả.\n   - BẮT BUỘC giữ lại toàn bộ các trend riêng biệt thỏa mãn điều kiện lọc trên, tuyệt đối không được bỏ sót, tự ý xóa bỏ hoặc ngộp chung các trend đủ điều kiện vào nhau.\n\n5. Số lượng kênh và video: Bạn không cần đếm chính xác, hệ thống sẽ tự đếm dựa trên IDs bài viết bạn trả về. Bạn chỉ cần trả về mảng crawled_data_ids chứa TẤT CẢ các ID của các video thuộc Trend đã gộp.";

const reflection_prompt = "\n\nBƯỚC TỰ KIỂM LỖI & SỬ A SAI (REFLECTION LOOP):\nTrước khi trả ra kết quả cuối cùng, hãy tự đóng vai trò là một người kiểm duyệt khó tính và đánh giá lại danh sách trend vừa dự thảo:\n1. Đã có trend nào vi phạm quy tắc bộ nhớ ở trên chưa? (Ví dụ: Bạn có đang gom chung scandal trốn thuế của Ji Chang Wook và đám cưới của Hà Du Quân lại thành một nhóm \"Tin tức người nổi tiếng\" không? Nếu có, hãy tách chúng ra ngay lập tức thành hai trend riêng biệt!).\n2. Tên các trend đã có địa danh cụ thể (ví dụ: Miền Tây, Hải Phòng, Đồng Nai...) nếu dữ liệu gốc có đề cập chưa?\nHãy thực hiện sửa sai và chỉ trả về danh sách các trend đã được hoàn thiện 100%.";

const fullPrompt = `${base_prompt}\n${memoryPrompt}\n${historyPrompt}\n${reflection_prompt}\n\nDỮ LIỆU CÁC TREND THÔ:\n${trendsContext}`;

return [{
    json: {
        prompt: fullPrompt,
        gemini_api_key: input.gemini_api_key,
        raw_trends_count: rawTrends.length
    }
}];

