{
  "contents": [{
    "parts": [{
      "text": "{{ $json.prompt }}"
    }]
  }],
  "generationConfig": {
    "responseMimeType": "application/json",
    "responseSchema": {
      "type": "ARRAY",
      "description": "Danh sách các trends sau khi đã được gộp và lọc trùng",
      "items": {
        "type": "OBJECT",
        "properties": {
          "crawled_data_ids": {
            "type": "ARRAY",
            "items": {
              "type": "STRING"
            },
            "description": "Mảng chứa toàn bộ các ID video thuộc về trend này"
          },
          "trend_name": {
            "type": "STRING",
            "description": "Tên trend ngắn gọn và bắt tai"
          },
          "viral_reason": {
            "type": "STRING",
            "description": "Lý do viral cụ thể"
          },
          "content_ideas": {
            "type": "STRING",
            "description": "Gợi ý chính xác 3 câu Hook (3 giây đầu) cực kỳ cuốn hút, kích thích sự tò mò để KOL/KOC bắt đầu video đu trend này hiệu quả (đánh số thứ tự 1, 2, 3)."
          },
          "expert_commentary": {
            "type": "STRING",
            "description": "Nhận xét chuyên gia từ AI"
          },
          "trend_score": {
            "type": "INTEGER",
            "description": "Điểm số AI tự đánh giá từ 0-100"
          }
        },
        "required": ["crawled_data_ids", "trend_name", "viral_reason", "content_ideas", "expert_commentary", "trend_score"]
      }
    }
  }
}

parameters.jsCode:
const response = $input.all()[0].json;
const parts = response.candidates[0].content.parts[0].text;
let mergedTrends = [];
try {
    mergedTrends = JSON.parse(parts);
} catch(e) {}

const tokensUsed = response.usageMetadata ? response.usageMetadata.totalTokenCount : 0;

return [{
    json: {
        merged_trends: mergedTrends,
        response_raw: parts,
        tokens_used: tokensUsed
    }
}];
